(window.FJDATA=window.FJDATA||{})["method"]={"steps":[{"key":"discover","icon":"inputs","title":["الاستكشاف","Discover"],"stages":[{"text":["نتفق على قرار واحد وصاحبه واختبار قبوله.","One decision, its owner and its acceptance test are agreed."],"state":null,"evidence":null,"label":["الاستكشاف","Discovery"]},{"text":["يتحول الطلب إلى تكليف قابل للاختبار: المستخدم، والبيانات، والصلاحيات، وحالة ناجحة وأخرى فاشلة.","The request becomes a testable brief: the user, the data, the permissions, one passing case and one failing case."],"state":null,"evidence":null,"label":["المواصفة","Spec"]}],"drivers":[],"ledger":[{"id":"pilot","cid":"C-19","env":"none","status":"proposed","asOf":"2026-11-25","claim":["تجربة أولى في نطاق واحد: مهمة واحدة، ومالك للنتيجة، ومؤشر للقيمة، وشرط للتوسع أو التوقف.","A first pilot in one scope: one task, an owner for the outcome, a value measure, and a condition to scale or stop."],"proves":["منهج مكتوب ومعروض في الفيلم ١٠ وفي قسم البدء.","A written method, shown in film 10 and in the start section."],"film":10},{"id":"speed-claim","cid":"C-01","env":"none","status":"proposed","asOf":"2026-11-25","claim":["هدف تخطيطي: نموذج أولي محدد النطاق في أسبوعين إلى ستة أسابيع، مقابل سيناريو تقليدي توضيحي من ١٢ أسبوعًا أو أكثر.","Planning target: a scoped prototype in two to six weeks, against an illustrative traditional scenario of twelve weeks or more."],"proves":["إفادة المالك عن طريقة عملنا، معروضة هدفًا تخطيطيًا.","The owner’s statement of how we work, shown as a planning target."],"film":9}],"films":[[10,"closing"]]},{"key":"architect","icon":"architecture","title":["التصميم المعماري","Architect"],"stages":[{"text":["عقد البيانات، وقواعد الوصول، وتقسيم العمل إلى مسارات مستقلة.","The data contract, the access rules and the split into independent tracks."],"state":null,"evidence":null,"label":["البنية","Architecture"]}],"drivers":[{"text":["كل مسار يستلم الملفات والعقد التي يحتاجها فقط، فيقل ما يُقرأ بلا حاجة.","Each track receives only the files and the contract it needs, so less is read without need."],"state":"observed","evidence":["في هذه النسخة لكل مسار قائمة مصادر محددة وملفات يملكها، كما في قواعد العمل وعقد الصفحة.","In this edition each track has a named list of sources and the files it owns, as written in the working rules and the site contract."],"label":["هندسة السياق","Context engineering"]}],"ledger":[{"id":"data-layer","cid":"C-17","env":"none","status":"observed","asOf":"2026-11-25","claim":["طبقة بيانات سديد: ١٤٨ جدولًا عليها أمان على مستوى الصف، و٤٢٣ سياسة وصول.","SADEED’s data layer: 148 tables with row-level security and 423 access policies."],"proves":["قراءة إجمالية من القاعدة وقت المراجعة.","An aggregate read from the database at review time."],"film":null},{"id":"tool-layers","cid":"C-16","env":"none","status":"in_code","asOf":"2026-11-25","claim":["٣٤ تعريف أداة في مسار الدردشة، و٥ أدوات لمحرك FINN، و١٤ منفّذ تكامل. ثلاث طبقات لا تُجمع.","34 tool definitions in the chat path, 5 tools for FINN, 14 integration executors. Three layers that are never added together."],"proves":["أسماء معرّفة في المصدر، كل طبقة في سجلها.","Names defined in source, each layer in its own registry."],"film":null}],"films":[[3,"method"]]},{"key":"build","icon":"code","title":["البناء","Build"],"stages":[{"text":["مسارات مستقلة تُبنى في الوقت نفسه، ولا يعدّل مساران ملفًا واحدًا.","Independent tracks are built at the same time, and no two tracks edit one file."],"state":null,"evidence":null,"label":["البناء المتوازي","Parallel Build"]}],"drivers":[{"text":["تكليف مكتوب بحدود وعقد مخرجات قبل أي كود، فتقل إعادة العمل.","A written brief with limits and an output contract before any code, so there is less rework."],"state":"configured","evidence":["تكليف وكيل مكتوب لمستودع سديد بحدود صارمة وسبع مراحل وعقد مخرجات. تنفيذ مراحله غير مقاس في هذا العرض.","A written agent brief for the SADEED repository with hard limits, seven phases and an output contract. Execution of its phases is not measured in this showcase."],"label":["التطوير المبني على المواصفة","Spec-driven development"]},{"text":["العمل المستقل يُوزَّع على مسارات تعمل معًا، ونراجع كل تغيير قبل اعتماده.","Independent work is split across tracks that run together, and we review every change before it is accepted."],"state":"observed","evidence":["سجل التنفيذ المؤرخ ٢٥ نوفمبر ٢٠٢٦ يدوّن مسارات منفصلة لهذه النسخة. أثرها على المدة غير مقاس.","The execution log of 25 November 2026 records separate tracks for this edition. Their effect on duration is not measured."],"label":["وكلاء برمجة بالتوازي","Coding agents in parallel"]}],"ledger":[{"id":"pace","cid":"C-02","env":"none","status":"verified","asOf":"2026-11-25","claim":["٧٬٩٣٧ التزامًا في مستودع سديد منذ مايو ٢٠٢٦، في ١٢٧ يوم عمل نشط، منها ١٬٥٣٠ في آخر ٣٠ يومًا.","7,937 commits in the SADEED repository since May 2026, across 127 active days, 1,530 of them in the last 30 days."],"proves":["عددناها من سجل الإيداعات في المستودع نفسه.","Counted from the repository’s own git history."],"film":9},{"id":"dev-time","cid":"C-21","env":"none","status":"not_measured","asOf":"2026-11-25","claim":["زمن تطوير ميزة من الصفر، ونسبة تحسّن سرعتنا عبر الزمن.","Time to develop a feature from scratch, and how much faster we have become over time."],"proves":["لا يوجد تكليفان متكافئان مؤرّخان.","No two dated, comparable briefs exist."],"film":null}],"films":[[9,"method"]]},{"key":"integrate","icon":"integration","title":["التكامل","Integrate"],"stages":[{"text":["تلتقي المخرجات عند عقد بيانات واحد وتُربط بالواجهات الفعلية.","The outputs meet at one data contract and are connected to the real interfaces."],"state":null,"evidence":null,"label":["التكامل","Integration"]}],"drivers":[{"text":["قاعدة البيانات والنشر والتصميم والبريد خدمات موصولة تُستدعى، ولا تُبنى من الصفر.","Database, deployment, design and mail are connected services to call, not things to build from scratch."],"state":"observed","evidence":["٢٣ خدمة موصولة في ٢٥ نوفمبر ٢٠٢٦، و٣٥٣ ملف مهارة مكتوبة. «موصول» و«مكتوب» لا تعنيان مستخدمًا في الإنتاج.","23 services connected on 25 November 2026, and 353 written skill files. Connected and written do not mean used in production."],"label":["مكوّنات وخدمات يُعاد استخدامها","Reusable components and services"]}],"ledger":[{"id":"connected","cid":"C-03","env":"none","status":"observed","asOf":"2026-11-25","claim":["٢٣ نظامًا موصولًا بحساباتنا تعرض مجتمعة أكثر من ألف أداة قابلة للاستدعاء.","23 systems are connected to our accounts and together expose more than a thousand callable tools."],"proves":["قائمة الموصلات وأدواتها كما ظهرت في جلسة البناء.","The connector list and its tools as they appeared in the build session."],"film":1}],"films":[[1,"method"]]},{"key":"test","icon":"evidence","title":["الاختبار","Test"],"stages":[{"text":["تُفحص الاختبارات والصلاحيات وهوية النسخة. بوابات الأمان والجودة لا تُتخطى.","Tests, permissions and the build identity are checked. Security and quality gates are never skipped."],"state":null,"evidence":null,"label":["التحقق","Verification"]}],"drivers":[],"ledger":[{"id":"kpi-formula","cid":"C-04","env":"demo","status":"verified","asOf":"2026-11-25","claim":["١٦ من ٢٠ مع حضور كامل تعطي ٨٨٪ بوزن ٦٠/٤٠، و٨٦٪ بوزن ٧٠/٣٠.","16 of 20 with full attendance gives 88% at a 60/40 weight, and 86% at 70/30."],"proves":["الدالة نفسها واختبار القبول. أعدنا تشغيل الحالات الأربع فنجحت.","The function and its acceptance test. We re-ran all four cases, and they passed."],"film":5},{"id":"missing-target","cid":"C-05","env":"demo","status":"verified","asOf":"2026-11-25","claim":["المستهدف المفقود يعلّق النتيجة للمراجعة ولا يُحسب صفرًا.","A missing target sends the result to review instead of scoring zero."],"proves":["قبل التعديل فشل الاختبار: أعاد صفرًا والمتوقع قيمة فارغة تعني «قيد المراجعة». بعده نجحت ٤ حالات قبول.","Before the change the test failed: it returned 0 where null was expected. After it, 4 acceptance cases passed."],"film":2},{"id":"trace-method","cid":"C-09","env":"demo","status":"simulated","asOf":"2026-11-25","claim":["قبل التعديل نتتبّع الحقل من الواجهة إلى الاستعلام إلى صلاحية القارئ، ثم نختار إصلاحًا محدودًا.","Before changing anything, we trace a field from the view to the query to the reader’s permission, then choose a narrow fix."],"proves":["طريقة العمل معروضة خطوة بخطوة على مستودع اصطناعي.","The working method shown step by step on a synthetic repository."],"film":3}],"films":[[2,"method"],[5,"method"]]},{"key":"deploy","icon":"deployment","title":["النشر","Deploy"],"stages":[{"text":["نموذج يعمل يُعرض على بيانات عيّنة آمنة. العرض ليس منتجًا إنتاجيًّا.","A working prototype is shown on safe sample data. A demo is not a production product."],"state":null,"evidence":null,"label":["العرض","Demo"]}],"drivers":[{"text":["فحوص آلية قبل الدمج، ثم تحقق من النسخة على النطاق بعد النشر.","Automated checks before a merge, then verification of the build on the domain after release."],"state":"observed","evidence":["أربع مهام فحص نجحت على رأس الفرع الرئيسي، ومهمة النشر المرتبطة فشلت. وفي تحديث #455 مضت ١٧ دقيقة و٢٢٫٧٩١ ثانية من الدمج إلى التحقق.","Four CI jobs passed on the head of the main branch, and the linked deploy job failed. For update #455, 17 minutes 22.791 seconds passed from merge to verification."],"label":["فحوص آلية ونشر متصل","CI/CD"]}],"ledger":[{"id":"release-455","cid":"C-06","env":"production","status":"observed","asOf":"2026-11-22","claim":["في تحديث سديد #455 مضت ١٧ دقيقة و٢٢٫٧٩١ ثانية من الدمج إلى التحقق على النطاقين.","For SADEED update #455, 17 minutes 22.791 seconds passed from merge to verification on both domains."],"proves":["طابعان زمنيان مسجّلان للتحديث نفسه، والفرق بينهما ١٠٤٢٫٧٩١ ثانية.","Two recorded timestamps for the same update, 1042.791 seconds apart."],"film":8},{"id":"ci-vs-live","cid":"C-07","env":"production","status":"observed","asOf":"2026-11-25","claim":["نجاح الفحص ونجاح النشر نتيجتان منفصلتان، وكل واحدة تُقرأ من مصدرها.","A passing check and a successful release are separate results, each read from its own source."],"proves":["لقطة تدقيق مؤرخة: نتيجة كل مهمة في خط الفحص، ثم بصمة النسخة التي يخدمها النطاق.","A dated audit snapshot: each job in the pipeline with its own outcome, then the revision the domain serves."],"film":8}],"films":[[8,"method"]]},{"key":"improve","icon":"performance","title":["التحسين","Improve"],"stages":[{"text":["تعود الملاحظات إلى المواصفة، وتتكرر الدورة على تغيير أضيق.","Feedback returns to the spec, and the cycle repeats on a narrower change."],"state":null,"evidence":null,"label":["التكرار","Iteration"]}],"drivers":[],"ledger":[{"id":"human-review","cid":"C-22","env":"none","status":"not_measured","asOf":"2026-11-25","claim":["مشاهدة مستقلة للأفلام، وتشغيل على هاتف آيفون فعلي وفي محرك WebKit، ومراجعة نطق بشرية.","An independent audience viewing, playback on a physical iPhone and in WebKit, and a human pronunciation review."],"proves":["لم تُجرَ بعد.","Not done yet."],"film":null},{"id":"sadeed-flow","cid":"C-08","env":"demo","status":"simulated","asOf":"2026-11-25","claim":["في سديد يقترح النموذج، ويبقى الاعتماد عند المسؤول. إذا تغيّر الدليل لزمت مراجعة جديدة.","In SADEED the model proposes and the accountable person approves. If the evidence changes, a new review is required."],"proves":["مسار قرار كامل على بلاغ اصطناعي: ملخص يفرّق بين الدليل المسجل والمعلومة الناقصة، ثم نقطة اعتماد بشري.","A full decision path on a synthetic report: a summary that separates recorded evidence from what is missing, then a human approval point."],"film":4}],"films":[[4,"result"]]}]};
